<script setup lang="ts">import{onMounted,ref}from'vue';const guards=ref<any[]>([]),dorm=ref<any[]>([]),audits=ref<any[]>([]);const auth=()=>({Authorization:sessionStorage.getItem('visitor-authorization')||''});onMounted(async()=>{const [g,d,a]=await Promise.all(['/api/visitor/admin/guard-records','/api/visitor/admin/dormitory-records','/api/visitor/admin/audit-logs'].map(u=>fetch(u,{headers:auth()})));if(g.ok)guards.value=await g.json();if(d.ok)dorm.value=await d.json();if(a.ok)audits.value=await a.json()});</script>
<template><header><p class="eyebrow">REPORTS</p><h2>综合查询与审计</h2></header><h3>进出记录</h3><p>{{guards.length}} 条</p><h3>住宿记录</h3><p>{{dorm.length}} 条</p><h3>操作审计</h3><div class="table-wrap"><table><thead><tr><th>来访编号</th><th>操作</th><th>操作人</th><th>时间</th></tr></thead><tbody><tr v-for="(a,i) in audits" :key="i"><td>{{a.visitId}}</td><td>{{a.action||'BED_CHANGED'}}</td><td>{{a.operator}}</td><td>{{a.operatedAt}}</td></tr></tbody></table></div></template>
